import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-footer',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './footer.component.html',
  styleUrls: ['./footer.component.css']
})
export class FooterComponent {
  currentYear = new Date().getFullYear();
}
<footer class="border-t border-border py-8 px-6">
  <div class="max-w-6xl mx-auto flex flex-col md:flex-row items-center justify-between gap-4 text-sm text-muted-foreground">
    <div class="flex items-center gap-3">
      <img src="assets/garagem r2 logo.png" alt="Garagem R2" class="h-8 w-auto" />
      <span>© {{ currentYear }} Garagem R2 Estética Automotiva</span>
    </div>
    <div>Feito com cuidado para quem ama carros.</div>
  </div>
</footer>
